const LEAF = svg(`
  <path d="M32 54C16 44 10 28 16 16c14 2 24 14 24 30 0 4-4 8-8 8z"/>
  <path d="M20 36c8-2 14-8 16-16"/>`);

export function posMark(name) {
  const hit = MARKS.find(([re]) => re.test(name || ''));
  return hit ? hit[1] : LEAF;
}
